"use strict";
// An event stream as client libraries make them: a class whose only
// protocol method is Symbol.asyncIterator, which produces each event after a
// delay and counts what it produced, so a consumer that reads ahead shows.
class Stream {
  constructor(count, ms) {
    this.count = count;
    this.ms = ms;
    this.produced = 0;
    this.returned = false;
    this.thrown = "";
  }
  [Symbol.asyncIterator]() {
    const stream = this;
    let index = 0;
    return {
      async next() {
        if (index >= stream.count) return { value: undefined, done: true };
        await new Promise((resolve) => setTimeout(resolve, stream.ms));
        stream.produced++;
        console.log(`  [island] produces ${index}`);
        return { value: { type: "event", index: index++ }, done: false };
      },
      async return(value) {
        stream.returned = true;
        console.log("  [island] return called");
        return { value, done: true };
      },
      async throw(error) {
        stream.thrown = String(error && error.message);
        throw error;
      },
    };
  }
}
exports.Stream = Stream;
exports.open = (count, ms) => new Stream(count, ms);
exports.openLater = async (count, ms) => new Stream(count, ms);
// The island consumes an async iterable of the program, one value at a
// time, and stops early.
exports.consume = async (iterable, stopAt) => {
  const seen = [];
  for await (const value of iterable) {
    console.log(`  [island] got ${value}`);
    seen.push(value);
    if (value === stopAt) break;
  }
  return seen.join(",");
};
